INSERT INTO metric_definition (code, version, name, unit, definition, formula, applies_to, cautions) VALUES
('venue_visits',1,'Venue visits','visits','People entering the venue in the period (a person visiting twice counts twice).',NULL,'{venue}','Venue traffic is NOT ad exposure.'),
('ots_visits',1,'Opportunity to see (visits)','visits','Venue visits whose path enters the asset viewing zone.','venue_visits x p_in_view_zone','{cstore_screen,hotel_screen,mall_screen}',NULL),
('ad_contacts_ots',1,'Ad contacts (opportunity to see)','contacts','Times a person is in the viewing zone while this ad is displayed (digital) or while at the face (static). Not attention-adjusted.','see lib/measurement/models.ts','{*}','Contacts are not people: one person can generate many contacts.'),
('est_impressions',1,'Estimated impressions','contacts','Ad contacts multiplied by a notice/attention factor.','ad_contacts_ots x p_notice','{*}','Notice factor is an assumption unless measured.'),
('verified_plays',1,'Verified ad plays','plays','Proof-of-play records from the CMS for the creative in the period.','COUNT(proof_of_play)','{cstore_screen,hotel_screen,mall_screen}',NULL),
('unique_reach',1,'Unique reach','people','Deduplicated people with an opportunity to see across a venue set.','licensed overlap data only','{network}','Unavailable without licensed overlap data.'),
('avg_frequency',1,'Average frequency','contacts per person','Gross contacts / unique reach.','gross_contacts / unique_reach','{network}','Unavailable without reach.'),
('gross_contacts',1,'Gross contacts','contacts','Sum of contacts across assets (duplicates included).','SUM(asset contacts)','{network}',NULL),
('workers_within_radius',1,'Jobs located within radius (workplace)','jobs','LODES WAC all-jobs (C000) for 2020 blocks whose internal point lies within the radius of the venue.','SUM(C000) over blocks within r','{venue}','Counts jobs at workplaces, not people present, not visitors, not residents.'),
('aadt_nearest_road',1,'AADT on nearest HPMS segment','vehicles per day','Two-way annual average daily traffic on the nearest HPMS road segment within the search radius.','max AADT among segments within 60 m','{venue}','Vehicles passing a nearby road; not venue visits and not visibility of a specific face.'),
('occupancy',1,'Occupancy','share','Booked capacity-unit-days / available capacity-unit-days in the date range.','see lib/inventory/occupancy.ts','{*}','Uses bookings, never invoices.');

